package com.fitfinance.dto;
import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate;
public final class EntryDtos {private EntryDtos(){} public record EntryRequest(@NotBlank @Size(max=120)String title,@Positive BigDecimal amount,@Size(max=32)String category,@NotNull LocalDate date,@Size(max=500)String description,@Positive Integer durationMinutes,@PositiveOrZero Integer caloriesBurned,@Positive BigDecimal weight,@PositiveOrZero Integer steps,@PositiveOrZero Integer calories,@Positive BigDecimal targetValue,@PositiveOrZero BigDecimal currentValue,@Size(max=24)String unit,LocalDate deadline,@Size(max=24)String status){} public record EntryResponse(Long id,String kind,String title,BigDecimal amount,String category,LocalDate date,String description,Integer durationMinutes,Integer caloriesBurned,BigDecimal weight,Integer steps,Integer calories,BigDecimal targetValue,BigDecimal currentValue,String unit,LocalDate deadline,String status){} }
